const body = $input.item.json.body || {};
const query = $input.item.json.query || {};
const channel = body.channel || query.channel || "unknown";
let sender_id, text, lang, phone_number_id;
if (channel === "website_widget") {
  sender_id = body.session_id;
  text = (body.message || "").trim();
  lang = body.lang || "en";
} else if (channel === "whatsapp") {
  sender_id = body.From || body.from;
  text = (body.Body || body.body || "").trim();
  lang = "en";
} else if (channel === "instagram" || channel === "facebook") {
  const entry = body.entry && body.entry[0];
  const messaging = entry && (entry.messaging || (entry.changes && entry.changes[0] && entry.changes[0].value && entry.changes[0].value.messages));
  const msg = messaging && messaging[0];
  sender_id = msg && (msg.sender && msg.sender.id || msg.from);
  text = (msg && msg.message && msg.message.text || "").trim();
  lang = "en";
} else if (channel === "tawkto") {
  sender_id = body.chatId || (body.visitor && body.visitor.name);
  text = (body.message && (body.message.text || body.message) || "").trim();
  lang = "en";
} else {
  sender_id = "unknown";
  text = (body.message || "").trim();
  lang = "en";
}
return { json: {
  session_id: body.session_id || sender_id || "unknown",
  sender_id: sender_id || "unknown",
  text: text,
  channel: channel,
  lang: lang,
  hotel_slug: body.hotel_slug || "hotel",\n  phone_number_id: phone_number_id || null,
  timestamp: new Date().toISOString()
} };

const data = $input.item.json || {};
const text = String(data.text || '');

if (text.trim().length < 3) {
  return { json: { ...data, lang: data.lang || 'en' } };
}

// STEP 1: Unicode range detection (non-Latin scripts — near 100% accurate)
const scriptRanges = [
  { lang: 'ar', regex: /[\u0600-\u06FF]/ },
  { lang: 'zh', regex: /[\u4E00-\u9FFF\u3400-\u4DBF]/ },
  { lang: 'ja', regex: /[\u3040-\u309F\u30A0-\u30FF]/ },
  { lang: 'ko', regex: /[\uAC00-\uD7AF]/ },
  { lang: 'ru', regex: /[\u0400-\u04FF]/ },
  { lang: 'th', regex: /[\u0E00-\u0E7F]/ },
  { lang: 'he', regex: /[\u0590-\u05FF]/ },
  { lang: 'el', regex: /[\u0370-\u03FF]/ },
  { lang: 'hi', regex: /[\u0900-\u097F]/ },
];
for (const script of scriptRanges) {
  if (script.regex.test(text)) {
    return { json: { ...data, lang: script.lang } };
  }
}

const tLower = text.toLowerCase();

// STEP 2: Tier 1 — unique multi-word phrases (1 match = definite detection)
// These phrases are impossible in English
const tier1 = {
  fr: ["bonjour","bonsoir","merci beaucoup","s'il vous","je voudrais","je suis","chambre disponible","comment allez","bienvenue","qu'est-ce"],
  es: ["hola","buenos dias","buenas tardes","buenas noches","gracias","habitacion","desayuno incluido","por favor","como estas"],
  de: ["guten morgen","guten tag","guten abend","danke schon","ich mochte","wie viel kostet","zimmer frei","auf wiedersehen"],
  it: ["buongiorno","buonasera","grazie mille","vorrei prenotare","camera disponibile","buona notte","prego"],
  pt: ["bom dia","boa tarde","boa noite","obrigado","obrigada","quarto disponivel","cafe da manha","bem-vindo"],
  nl: ["goedemorgen","goedemiddag","dank u wel","kamer beschikbaar","alstublieft","goedenavond"],
  tr: ["gunaydin","iyi aksamlar","tesekku ederim","oda musait","rezervasyon yapmak","hosgeldiniz"],
};
for (const lang in tier1) {
  for (const phrase of tier1[lang]) {
    if (tLower.includes(phrase)) {
      return { json: { ...data, lang: lang } };
    }
  }
}

// STEP 3: Tier 2 — weighted function words (min 3 matches required to avoid false positives)
// Words chosen to NOT overlap with common English words
const tier2 = {
  fr: ['les','est','qui','que','pour','avec','nous','vous','ils','elles','une','des','pas','sur','tres','mais','donc','bien','tout','alors','cette','aussi','quoi','quel','quelle','notre','votre','leur'],
  es: ['los','las','del','para','con','pero','hay','muy','como','cuando','donde','porque','tambien','todo','este','esta','tiene','tienen','hacer','nosotros','vosotros','ellos','ellas'],
  de: ['und','ist','nicht','auch','noch','dann','beim','nach','mehr','kann','will','sind','war','wird','habe','haben','mein','meine','keine','ihnen','ihrer','seine','unsere'],
  it: ['gli','sono','hanno','questo','questa','tutto','tutti','come','dove','quando','anche','pero','cosi','molto','bene','loro','siamo','avere','essere','nostro','vostro'],
  pt: ['sao','tem','com','por','para','tambem','quando','como','tudo','muito','aqui','nosso','nossa','voce','voces','eles','elas','sera','estar','fazer'],
  nl: ['het','zijn','heeft','niet','ook','meer','dan','nog','maar','want','omdat','toen','voor','door','over','naar','uit','bij','aan','van','wij','zij','jullie'],
  tr: ['var','yok','icin','gibi','ama','daha','cok','nasil','nerede','zaman','cunku','birlikte','hepsi','hic','bile','sadece','kadar','butun','olmak','etmek'],
};
const wordTokens = tLower.split(/\s+/);
const scores = {};
for (const lang in tier2) {
  let score = 0;
  for (const word of wordTokens) {
    const clean = word.replace(/[^a-z\u00e0-\u017e]/gi, '');
    if (tier2[lang].includes(clean)) score++;
  }
  scores[lang] = score;
}
const THRESHOLD = 3;
let bestLang = 'en';
let bestScore = 0;
for (const lang in scores) {
  if (scores[lang] >= THRESHOLD && scores[lang] > bestScore) {
    bestScore = scores[lang];
    bestLang = lang;
  }
}
return { json: { ...data, lang: bestLang } };

const normData = $('Normalise Message').first().json || {};
const g360 = $('Fetch Guest 360 Memory').first().json || {};
const rag = $('Retrieve Semantic Knowledge').first().json || {};
const lang = ($('Detect Language').first().json && $('Detect Language').first().json.lang) || 'en';
const history = (normData.conversation_history || []).slice(-8);

const guestMemoryBlock = g360.context_block || 'GUEST 360 MEMORY:\nGuest recognition active — standard guest profile.';
const ragKnowledgeBlock = rag.context_block || 'RELEVANT HOTEL KNOWLEDGE:\nStandard hotel amenities and guest services active.';

const historyText = history.length > 0
  ? '\nCONVERSATION HISTORY (last ' + history.length + ' turns):\n' +
    history.map(function(t) { return '[' + (t.role === 'assistant' ? 'Assistant' : 'Guest') + ']: ' + t.content; }).join('\n') + '\n'
  : '';

const systemPrompt =
  'You are the Ever Guest OS Hospitality Concierge for ' + (normData.hotel_slug || 'our property') + '.\n' +
  'You are a sophisticated, warm, and highly capable luxury hospitality concierge assistant.\n\n' +
  guestMemoryBlock + '\n\n' +
  ragKnowledgeBlock + '\n\n' +
  historyText + '\n' +
  'CANONICAL HOSPITALITY TOOL INSTRUCTIONS:\n' +
  'You have access to real-time property management tools. When the guest expresses an operational request, ' +
  'you MUST output a tool execution tag at the very end of your response on a new line in this format:\n' +
  '[TOOL_CALL: name=tool_name, arguments={"arg1": "value1"}]\n\n' +
  'AVAILABLE TOOLS:\n' +
  '- check_room_availability: arguments: {"check_in": "YYYY-MM-DD", "check_out": "YYYY-MM-DD", "guests": 2}\n' +
  '- create_reservation: arguments: {"guest_name": "...", "room_type": "...", "check_in": "YYYY-MM-DD", "check_out": "YYYY-MM-DD"}\n' +
  '- place_dining_order: arguments: {"room_number": "101", "items": [{"name": "...", "quantity": 1}]}\n' +
  '- request_room_amenity: arguments: {"room_number": "101", "item": "towels", "quantity": 2}\n' +
  '- request_late_checkout: arguments: {"room_number": "101", "requested_time": "14:00"}\n' +
  '- submit_maintenance_ticket: arguments: {"room_number": "101", "category": "plumbing|ac|electrical|general", "description": "..."}\n' +
  '- escalate_to_staff: arguments: {"reason": "Guest requested human agent or complex issue"}\n\n' +
  'LEAD CAPTURE INSTRUCTIONS:\n' +
  'When an unrecognized guest enquires about booking rooms, collect full name and email/phone, then append:\n' +
  '[LEAD: name=Full Name, email=email@example.com, phone=+1234567890, checkin=YYYY-MM-DD, checkout=YYYY-MM-DD]\n\n' +
  'HANDOFF INSTRUCTIONS:\n' +
  'If guest asks for a human or shows high frustration, prepend [HANDOFF_REQUIRED] and call escalate_to_staff.\n\n' +
  'Detected language: ' + lang + '. Always reply naturally in the guest\'s language.';

return [{ json: {
  ...normData,
  text: normData.text,
  systemPrompt: systemPrompt
} }];

const agentRaw = $input.item.json;
const origData = $('Build System Prompt').first().json || {};

// Parse AI output
let rawContent = null;
if (agentRaw.output !== undefined && agentRaw.output !== null && String(agentRaw.output).trim() !== '') {
  rawContent = String(agentRaw.output);
} else if (agentRaw.choices) {
  rawContent = (agentRaw.choices[0] && agentRaw.choices[0].message && agentRaw.choices[0].message.content) || null;
} else if (agentRaw.data && agentRaw.data.choices) {
  rawContent = (agentRaw.data.choices[0] && agentRaw.data.choices[0].message && agentRaw.data.choices[0].message.content) || null;
}

const fallbackReply = "I apologize, I'm having a technical issue right now. Please contact hotel reception and we will be delighted to assist you.";
let reply = rawContent || fallbackReply;

// ── 1. Parse Canonical Tool Calls ──────────────────────────────────────────
let has_tool_call = false;
let tool_name = null;
let tool_arguments = {};

const toolMatch = reply.match(/\[TOOL_CALL:\s*name=([a-z0-9_]+),\s*arguments=([^\]]+)\]/i);
if (toolMatch) {
  has_tool_call = true;
  tool_name = toolMatch[1].trim();
  try {
    tool_arguments = JSON.parse(toolMatch[2].trim());
  } catch (e) {
    tool_arguments = {};
  }
  reply = reply.replace(/\[TOOL_CALL:[^\]]+\]/g, '').trim();
}

// ── 2. Parse HANDOFF tag ───────────────────────────────────────────────────
let handoff_required = false;
if (reply.includes('[HANDOFF_REQUIRED]')) {
  handoff_required = true;
  reply = reply.replace('[HANDOFF_REQUIRED]', '').trim();
}

const guestText = (origData.text || '').toLowerCase();
const humanKeywords = [
  'speak to someone','talk to someone','human please','real person',
  'live agent','customer service','manager please','need a human','transfer me'
];
if (!handoff_required && humanKeywords.some(function(kw) { return guestText.includes(kw); })) {
  handoff_required = true;
  reply = "Of course! Let me connect you with a member of our team right away. Please hold for just a moment.";
}

// ── 3. Parse Legacy Intents for Backwards Compatibility ─────────────────────
let order_intent = null;
const orderMatch = reply.match(/\[ORDER_INTENT:\s*category=([^\]]+)\]/);
if (orderMatch) {
  order_intent = orderMatch[1].trim();
  reply = reply.replace(/\[ORDER_INTENT:[^\]]+\]/g, '').trim();
  if (!has_tool_call) {
    has_tool_call = true;
    tool_name = 'place_dining_order';
  }
}

let service_intent = null;
const svcMatch = reply.match(/\[SERVICE_INTENT:\s*type=([^\]]+)\]/);
if (svcMatch) {
  service_intent = svcMatch[1].trim();
  reply = reply.replace(/\[SERVICE_INTENT:[^\]]+\]/g, '').trim();
  if (!has_tool_call) {
    has_tool_call = true;
    tool_name = 'request_room_amenity';
  }
}

let booking_intent = false;
if (reply.includes('[BOOKING_INTENT]')) {
  booking_intent = true;
  reply = reply.replace('[BOOKING_INTENT]', '').trim();
  if (!has_tool_call) {
    has_tool_call = true;
    tool_name = 'check_room_availability';
  }
}

// ── 4. Parse LEAD tag ─────────────────────────────────────────────────────
let lead_captured = false;
let lead_data = null;
const leadMatch = reply.match(/\[LEAD:\s*([^\]]+)\]/);
if (leadMatch) {
  lead_captured = true;
  const parts = leadMatch[1];
  const extract = function(key) {
    const m = parts.match(new RegExp(key + '=([^,\\]]+)'));
    return m ? m[1].trim() : null;
  };
  lead_data = {
    name: extract('name'),
    email: extract('email'),
    phone: extract('phone'),
    checkin: extract('checkin'),
    checkout: extract('checkout'),
  };
  reply = reply.replace(/\[LEAD:[^\]]+\]/g, '').trim();
}

return [{
  json: {
    session_id: origData.session_id,
    sender_id: origData.sender_id,
    channel: origData.channel,
    lang: origData.lang,
    hotel_slug: origData.hotel_slug,
    text: origData.text || '',
    timestamp: origData.timestamp || new Date().toISOString(),
    reply: reply,
    has_tool_call: has_tool_call,
    tool_name: tool_name,
    tool_arguments: tool_arguments,
    handoff_required: handoff_required,
    order_intent: order_intent,
    service_intent: service_intent,
    booking_intent: booking_intent,
    lead_captured: lead_captured,
    lead_data: lead_data
  }
}];

// Email node response discarded — restore clean guest data from Extract AI Reply
const orig = $('Extract AI Reply').item.json;
return { json: orig };

// ── WEBHOOK SIGNATURE VALIDATION [HARDENING: Security] ───────────────────────
// Bypass mode (dev). Set BYPASS=false and configure per-channel HMAC when
// channel credentials are live.
// Twilio: X-Twilio-Signature (HMAC-SHA1 of URL + sorted POST params)
// Meta:   X-Hub-Signature-256 (HMAC-SHA256 of raw body with app secret)
// Widget: X-Widget-Token (shared secret from client .env)
const headers = $input.item.json.headers || {};
const body    = $input.item.json.body    || {};
const BYPASS  = true; // TODO: flip to false when channel creds are live
return { json: { ...$input.item.json, signature_valid: BYPASS || false, sig_bypass: BYPASS } };

// ── RATE LIMITING [HARDENING: Abuse Protection] ──────────────────────────────
// Sliding window using n8n static workflow data. Moves to Redis in Phase 2.
// Limits: 20 msg/min per sender | 100 msg/min per hotel
const s    = $getWorkflowStaticData('global');
const body = $input.item.json.body || {};
const now  = Date.now();
const WIN  = 60000;
if (!s.rl) s.rl = {};
const bump = (k, max) => {
  const w = s.rl[k] || { n: 0, t: now };
  if (now - w.t > WIN) { w.n = 0; w.t = now; }
  w.n++; s.rl[k] = w;
  return w.n > max;
};
const sid   = String(body.session_id  || 'unknown');
const hotel = String(body.hotel_slug  || 'unknown');
const se    = bump('s:' + sid,   20);
const he    = bump('h:' + hotel, 100);
return { json: { ...$input.item.json, rate_exceeded: se || he, rate_reason: se ? 'sender' : he ? 'hotel' : null } };

// ── CHECK FEEDBACK PENDING [HARDENING: Feedback Collection] ─────────────────
// If the guest sent feedback (1-5 reply), capture it and store.
// If feedback is pending AND 5+ min have passed, intercept the next message
// to collect the feedback rating before processing the actual request.
const s   = $getWorkflowStaticData('global');
const body = $input.item.json.body || {};
const sid  = body.session_id || 'unknown';
const fp   = (s.feedbackPending || {})[sid];
const DELAY = 5 * 60 * 1000; // 5 minutes
let feedback_due  = false;
let feedback_data = null;
if (fp && fp.pending && (Date.now() - fp.set_at) >= DELAY) {
  feedback_due  = true;
  feedback_data = fp;
  if (!s.feedbackPending) s.feedbackPending = {};
  delete s.feedbackPending[sid];
}
return { json: { ...$input.item.json, feedback_due, feedback_data } };

// Prepare the feedback message to send to guest
const d    = $input.item.json;
const fd   = d.feedback_data || {};
const hotel = fd.hotel_slug || 'us';
return { json: {
  session_id: d.body && d.body.session_id || fd.session_id || 'unknown',
  sender_id:  fd.sender_id || 'unknown',
  channel:    fd.channel   || 'unknown',
  hotel_slug: fd.hotel_slug || 'hotel',
  hotelInfo:  {},
  reply: 'Hi! Thank you for chatting with us today. How would you rate your experience?\n\n' +
         '⭐ Please reply with a number 1 to 5 (5 = excellent)\n\n' +
         'Your feedback helps us serve you better. We hope to welcome you soon! 🙏',
  is_feedback_request: true,
  handoff_required: false, lead_captured: false, lead_data: null
} };

// Extract conversation history from Supabase response
const response  = $input.item.json;
const prev      = $('Detect Language').item.json;
let history = [];
try {
  const turns = Array.isArray(response) ? response : [];
  history = turns.slice(-10).map(t => ({ role: t.role || 'user', content: t.content || '' }));
} catch(e) { /* non-blocking — continue without history */ }
return { json: { ...prev, conversation_history: history } };

// ── FEEDBACK SCHEDULER [HARDENING: Feedback Collection] ─────────────────────
const s    = $getWorkflowStaticData('global');
const data = $input.item.json;
if (!s.feedbackPending) s.feedbackPending = {};
// Only schedule feedback for non-handoff conversations
if (!data.handoff_required) {
  s.feedbackPending[data.session_id] = {
    pending:    true,
    channel:    data.channel,
    hotel_slug: data.hotel_slug,
    sender_id:  data.sender_id,
    set_at:     Date.now()
  };
}
return { json: { ...data, feedback_eligible: !data.handoff_required } };

const botResp = $input.item.json;
const reply = botResp.reply || null;
const ignored = botResp.ignored || false;
const agent_joining = botResp.agent_joining || false;
const origData = $('Extract AI Reply').item.json;
return { json: { ...origData, reply: reply, ignored: ignored, agent_joining: agent_joining } };
